from django.db import migrations


# Apna's "interview_fixed" was imported as In Progress while the portal had no
# interview stage, its wording kept in remarks as "Status in sheet: ...". Now
# that the stage exists those candidates move to it -- but only the ones still
# In Progress: anyone HR has since moved on stays where HR put them.
SHEET_STATUS = 'status in sheet:'
INTERVIEW = ('interview_fixed', 'interview fixed', 'interview scheduled')


def _sheet_status(remarks):
    for line in (remarks or '').splitlines():
        line = line.strip().lower()
        if line.startswith(SHEET_STATUS):
            return line[len(SHEET_STATUS):].strip()
    return ''


def _imported_as_interview(Candidate, action):
    rows = Candidate.objects.filter(action=action, remarks__icontains=SHEET_STATUS)
    return [
        pk for pk, remarks in rows.values_list('pk', 'remarks')
        if any(word in _sheet_status(remarks) for word in INTERVIEW)
    ]


def interview_fixed_to_interview_scheduled(apps, schema_editor):
    Candidate = apps.get_model('onboarding', 'Candidate')
    ids = _imported_as_interview(Candidate, 'In Progress')
    Candidate.objects.filter(pk__in=ids, action='In Progress').update(action='Interview Scheduled')


def interview_scheduled_back_to_in_progress(apps, schema_editor):
    Candidate = apps.get_model('onboarding', 'Candidate')
    ids = _imported_as_interview(Candidate, 'Interview Scheduled')
    Candidate.objects.filter(pk__in=ids, action='Interview Scheduled').update(action='In Progress')


